def _remove_stale_temps(self) -> None:
    for name in (self._path + ".tmp", self._ckp_path + ".tmp",
                 self._marker_path + ".tmp", self._cmp_path + ".tmp"):
        try:
            os.unlink(name)
        except FileNotFoundError:
            pass
    # Half-published snapshot sidecars left by a kill mid-token-mint.
    for name in os.listdir(self._dir):
        if (name.startswith(_SNAPSHOT_PREFIX)
                and name.endswith(".tmp")):
            try:
                os.unlink(os.path.join(self._dir, name))
            except OSError:
                pass
    # Half-published *lease* sidecars are removed only when they are
    # older than the lease TTL: a fresh ``.tmp`` is a reader's in-flight
    # atomic heartbeat publish and must not be touched, whereas one left
    # by a kill is stale by seconds and can never be renamed again.
    now = time.time()
    for name in os.listdir(self._dir):
        if not (name.startswith(_LEASE_PREFIX)
                and name.endswith(".tmp")):
            continue
        full = os.path.join(self._dir, name)
        try:
            age = now - os.stat(full).st_mtime
        except OSError:
            continue
        if age > _LEASE_TTL:
            try:
                os.unlink(full)
            except OSError:
                pass

