def _classify_manifest(self, path: str, seq: int, sid: bytes,
                       block_good: dict):
    """Classify one ``wal.s`` sidecar as ``"manifest"``/``"legacy"``/bad.

    ``"manifest"`` is an intact block manifest whose checksum and
    sequence/identity agree with the name and whose every referenced
    block exists and verifies against the id in its own name;
    ``"legacy"`` is a former full-image copy that verifies the same way;
    anything torn, forged, mistyped, truncated or pointing at a
    disagreeing block is damaged and returns ``None``. Block verification
    is read once per block per sweep and memoised in ``block_good``
    (keyed by block id), so a block shared by several manifests is
    streamed through the fixed-size buffer at most once.
    """
    try:
        with open(path, "rb") as f:
            magic = f.read(4)
            if magic == _MANIFEST_MAGIC:
                raw = magic + f.read()
            else:
                raw = None
        if raw is not None:
            block_ids = _decode_manifest(raw, seq, sid)
            if block_ids is None:
                return None
            for block_id in block_ids:
                good = block_good.get(block_id)
                if good is None:
                    good = _verify_block_file(
                        os.path.join(self._dir, _block_name(block_id)),
                        block_id)
                    block_good[block_id] = good
                if not good:
                    return None
            return "manifest"
    except OSError:
        return None
    # Not a manifest: the only other trusted shape is a former
    # full-image copy (a WAL2 snapshot header followed by put frames).
    return "legacy" if _verify_snapshot_blob(path, seq, sid) else None

